ids = ["LY-537","LY-538","LY-539","LY-540","LY-541","LY-542","LY-543","LY-601","LY-602","LY-603","LY-604","LY-605","LY-606","LY-607","LY-608","LY-609","LY-610","LY-611","LY-612","LY-613"]
assert [p["case_id"] for p in P] == ids, "id order mismatch"
for p in P:
    (base / f"{p['case_id']}.json").write_text(json.dumps(p, ensure_ascii=False, indent=1), encoding="utf-8")

# precise validation: open only this batch's files, by exact id list
ok = 0
cm = ru = di = 0
for cid in ids:
    d = json.loads((base / f"{cid}.json").read_text(encoding="utf-8"))
    assert d["case_id"] == cid
    assert set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger","systems_used"}
    assert 0 <= d["confidence"] <= 1 and d["prediction_text"] and d["basis"]
    t = d["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
    cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
    ok += 1
print(f"written={ok} changed_main={cm} reserve_used={ru} disputed={di}")
